<?php require_once 'bootstrap.php';$u=require_login();$id=(string)($_GET['id']??'');$st=db()->prepare('SELECT * FROM generated_documents WHERE sic_id=? AND owner_sic_id=?');$st->execute([$id,$u['sic_id']]);$d=$st->fetch();if(!$d){http_response_code(404);exit('Documento non trovato');}$payload=json_decode($d['payload_json']??'{}',true)?:[];?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=h($d['title'])?></title><style>body{font-family:Arial,sans-serif;margin:20mm;color:#071B33}.head{border-bottom:3px solid #22C55E;padding-bottom:12px}.sic{font-family:monospace;font-size:11px;color:#607284}.body{white-space:pre-wrap;line-height:1.5}@media print{button{display:none}@page{size:A4;margin:18mm}}</style></head><body><div class="head"><h1><?=h($d['title'])?></h1><div class="sic"><?=h($d['sic_id'])?></div></div><p><b>Data:</b> <?=h($payload['date']??date('Y-m-d'))?></p><div class="body"><?=h($payload['body']??'')?></div><p class="sic">SHA-256: <?=h($d['sha256'])?></p><button onclick="print()">Stampa / Salva come PDF</button></body></html>